def longest_common_prefix(strs: list[str]) -> str:
    if not strs:
        return ""

    # The longest common prefix of a set of strings is the same as the 
    # common prefix between the lexicographically smallest and largest strings.
    s1 = min(strs)
    s2 = max(strs)

    for i, char in enumerate(s1):
        if i >= len(s2) or char != s2[i]:
            return s1[:i]

    return s1
